from flask import Flask, redirect, url_for

app = Flask(__name__)

@app.route('/new')
def new():
    return 'Welcome to the new route!'

@app.route('/old')
def old():
    return redirect(url_for('new'))

if __name__ == '__main__':
    app.run(debug=True)
